"use client";

import { useState } from "react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { Logo } from "@/components/Logo";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { useAuth, UserRole } from "@/contexts/AuthContext";
import { toast } from "sonner";

const typeLabels: Record<string, { title: string; description: string }> = {
    talent: {
        title: "Join as Talent",
        description: "Showcase your skills and connect with casting directors",
    },
    director: {
        title: "Join as Casting Director",
        description: "Discover exceptional talent for your productions",
    },
    professional: {
        title: "Join as Industry Professional",
        description: "Showcase your craft and get hired for your next production",
    },
    admin: {
        title: "Join as Admin",
        description: "Manage and moderate the platform",
    },
};

export default function SignUp() {
    const params = useParams();
    const type = (params?.type as string) || "talent";
    const router = useRouter();
    const { signUp } = useAuth();
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    const [agreed, setAgreed] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const { title, description } = typeLabels[type] || typeLabels.talent;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (password !== confirmPassword) {
            toast.error("Passwords do not match");
            return;
        }

        setIsLoading(true);

        const role = (type as UserRole) || "talent";
        const { error } = await signUp(email, password, role);

        if (error) {
            toast.error(error);
            setIsLoading(false);
            return;
        }

        toast.success("Account created successfully!");

        // Route based on role
        const roleRoutes: Record<UserRole, string> = {
            talent: "/dashboard",
            director: "/director",
            professional: "/professional",
            admin: "/admin",
        };
        router.push(roleRoutes[role]);
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-background p-4">
            <div className="w-full max-w-md">
                <div className="text-center mb-8">
                    <Logo className="justify-center" />
                </div>

                <div className="bg-card rounded-2xl shadow-card p-8">
                    <div className="text-center mb-6">
                        <h1 className="text-2xl font-bold">{title}</h1>
                        <p className="text-muted-foreground mt-1">{description}</p>
                    </div>

                    {/* Social Login */}
                    <div className="space-y-3">
                        <Button variant="social" className="w-full" type="button">
                            <svg className="w-5 h-5" viewBox="0 0 24 24">
                                <path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
                                <path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
                                <path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
                                <path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
                            </svg>
                            Continue with Google
                        </Button>
                        <Button variant="social" className="w-full" type="button">
                            <svg className="w-5 h-5" viewBox="0 0 24 24" fill="currentColor">
                                <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
                            </svg>
                            Continue with Facebook
                        </Button>
                    </div>

                    <div className="relative my-6">
                        <div className="absolute inset-0 flex items-center">
                            <div className="w-full border-t border-border"></div>
                        </div>
                        <div className="relative flex justify-center text-xs uppercase">
                            <span className="bg-card px-2 text-muted-foreground">Or continue with email</span>
                        </div>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div>
                            <label className="text-sm font-medium mb-1.5 block">Email</label>
                            <Input
                                type="email"
                                placeholder="Enter your email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                            />
                        </div>
                        <div>
                            <label className="text-sm font-medium mb-1.5 block">Password</label>
                            <Input
                                type="password"
                                placeholder="Create a password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                            />
                        </div>
                        <div>
                            <label className="text-sm font-medium mb-1.5 block">Confirm Password</label>
                            <Input
                                type="password"
                                placeholder="Confirm your password"
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                required
                            />
                        </div>

                        <div className="flex items-start gap-2">
                            <Checkbox
                                id="terms"
                                checked={agreed}
                                onCheckedChange={(checked) => setAgreed(checked as boolean)}
                                className="mt-0.5"
                            />
                            <label htmlFor="terms" className="text-sm text-muted-foreground">
                                I agree to the{" "}
                                <Link href="/terms" className="text-foreground underline">Terms of Service</Link>
                                {" "}and{" "}
                                <Link href="/privacy" className="text-foreground underline">Privacy Policy</Link>
                            </label>
                        </div>

                        <Button type="submit" className="w-full" size="lg" disabled={!agreed || isLoading}>
                            {isLoading ? "Creating account..." : "Create Account"}
                        </Button>
                    </form>

                    <p className="text-xs text-center text-muted-foreground mt-6">
                        This site is protected by reCAPTCHA and the Google{" "}
                        <Link href="/privacy" className="underline">Privacy Policy</Link> and{" "}
                        <Link href="/terms" className="underline">Terms of Service</Link> apply.
                    </p>

                    <p className="text-center text-sm mt-6">
                        Already have an account?{" "}
                        <Link href="/sign-in" className="text-primary font-medium hover:underline">
                            Sign In
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
}
